window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e576538f6de26d3f"]={"versions": [{"id": "FIG-e576538f6de26d3f", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Einzelschritts innerhalb des AUTOSAR E2E Profile 4m Schutzmechanismus (<code>E2E_P04mProtect</code>). Das Diagramm visualisiert den Funktionsschritt „Write Message Result“ im Kontext der E2E-Bibliothek (Classic und Adaptive Platform).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Kontext / Funktion:</strong> <code>E2E_P04mProtect()</code>\n</li><li><strong>Eingangsdaten:</strong> <code>messageType</code> bzw. <code>MessageResult</code> (2-Bit-Wert)\n</li><li><strong>Zieldaten:</strong> Byte-Array <code>Data[]</code> am Index <code>[Offset + 12]</code>\n</li><li><strong>Knotenelemente:</strong> Startknoten (Initial Node), Aktionszustand (Action State) zur bitweisen Manipulation und Endknoten (Activity Final Node).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Start der Aktivität am Initialknoten.\n</li><li>Übergang zum Aktionsschritt: Kopieren des 2-Bit-Werts <code>MessageResult</code> in die Bits 2 und 3 des Bytes <code>Data[Offset + 12]</code> in Big-Endian-Reihenfolge.\n<ul class=\"fig-list\"><li>Bitweise Operation: <code>Data[Offset+12] = (Data[Offset+12] &amp; 0xCF) | ((messageType &amp; 0x03) &lt;&lt; 4)</code>\n</li></ul>\n</li><li>Direkter Übergang zum Activity Final Node und Beendigung des Schritts.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung nach <code>[PRS_E2E_00764]</code>. Bei der Implementierung ist zu beachten, dass in der mathematischen Formel des Aktionsblocks formal der Parametername <code>messageType</code> statt <code>MessageResult</code> als Quellvariable für das Bitfeld angegeben ist, maskiert mit <code>0x03</code> und nach links verschoben um 4 Bits (<code>&lt;&lt; 4</code>), während die Maske <code>0xCF</code> (Binär <code>1100 1111</code>) die Zielbits 4 und 5 (bei Zählung von LSB 0) bzw. Bits 2 und 3 (bei MSB-Zählung) zurücksetzt.</p>"}, {"id": "FIG-2ecaa5b2fcf875a5", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Einzelschritts innerhalb des AUTOSAR E2E Profile 4m Schutzmechanismus (<code>E2E_P04mProtect</code>). Das Diagramm visualisiert den Funktionsschritt „Write Message Result“ im Kontext der E2E-Bibliothek (Classic und Adaptive Platform).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Kontext / Funktion:</strong> <code>E2E_P04mProtect()</code>\n</li><li><strong>Eingangsdaten:</strong> <code>messageType</code> bzw. <code>MessageResult</code> (2-Bit-Wert)\n</li><li><strong>Zieldaten:</strong> Byte-Array <code>Data[]</code> am Index <code>[Offset + 12]</code>\n</li><li><strong>Knotenelemente:</strong> Startknoten (Initial Node), Aktionszustand (Action State) zur bitweisen Manipulation und Endknoten (Activity Final Node).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Start der Aktivität am Initialknoten.\n</li><li>Übergang zum Aktionsschritt: Kopieren des 2-Bit-Werts <code>MessageResult</code> in die Bits 2 und 3 des Bytes <code>Data[Offset + 12]</code> in Big-Endian-Reihenfolge.\n<ul class=\"fig-list\"><li>Bitweise Operation: <code>Data[Offset+12] = (Data[Offset+12] &amp; 0xCF) | ((messageType &amp; 0x03) &lt;&lt; 4)</code>\n</li></ul>\n</li><li>Direkter Übergang zum Activity Final Node und Beendigung des Schritts.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung nach <code>[PRS_E2E_00764]</code>. Bei der Implementierung ist zu beachten, dass in der mathematischen Formel des Aktionsblocks formal der Parametername <code>messageType</code> statt <code>MessageResult</code> als Quellvariable für das Bitfeld angegeben ist, maskiert mit <code>0x03</code> und nach links verschoben um 4 Bits (<code>&lt;&lt; 4</code>), während die Maske <code>0xCF</code> (Binär <code>1100 1111</code>) die Zielbits 4 und 5 (bei Zählung von LSB 0) bzw. Bits 2 und 3 (bei MSB-Zählung) zurücksetzt.</p>"}], "trans": [{"from": "FIG-e576538f6de26d3f", "to": "FIG-2ecaa5b2fcf875a5", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
